INSERT INTO mensajes (id, negocio_id, numero_cliente, contenido, tipo, intencion_detectada, agente_proceso, created_at) VALUES (85, 8, '+105437152186577', '¡Hola! Sí, aún tenemos disponibilidad. Tanto nuestras galletas como los brownies son deliciosos, pero muchos de nuestros clientes prefieren el brownie por su textura intensa. ¿Te gustaría realizar un pedido para el bloque 13?', 'salida', 'general', 'gemini', '"2026-09-05T21:48:04.000Z"');
