INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (449, 8, 17, 'general', 'gemini', 'Ando ocupada para contestar', '¡Hola! No te preocupes, soy Asistente de Admin NOMA y entiendo que estés ocupada. Quedo a tu disposición para cuando puedas atender tus consultas o pedidos.', 506, 0, '"2026-09-05T21:48:02.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (450, 8, 17, 'general', 'gemini', 'Salió en 10', '¡Hola! Soy Asistente de Admin NOMA, ¿en qué puedo ayudarte hoy? Si te refieres a un pedido o pago, por favor confírmame los detalles para poder asistirte de inmediato.', 805, 0, '"2026-09-05T21:48:03.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (451, 8, 22, 'general', 'gemini', 'Hola', '¡Hola! Bienvenido a Admin NOMA, soy tu Asistente virtual. ¿En qué puedo ayudarte hoy con nuestros productos o servicios?', 399, 0, '"2026-09-05T21:48:03.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (452, 8, 22, 'general', 'gemini', 'Me guardar 1 entonces', '¡Hola! Es un gusto saludarte. Tanto la galleta como el brownie son deliciosos, pero muchos de nuestros clientes prefieren el brownie por su textura intensa. ¿Deseas que te guarde una unidad de brownie o de galleta, y cuál sería tu dirección de entrega?', 245, 0, '"2026-09-05T21:48:03.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (453, 8, 22, 'error', 'none', 'Sí claro', 'Disculpa, el servicio de IA está temporalmente no disponible. Intenta de nuevo en un momento.', 0, 0, '"2026-09-05T21:48:04.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (454, 8, 22, 'general', 'gemini', 'No, no es primera vez', '¡Hola! Qué gusto saludarte de nuevo por aquí. Por lo general, el brownie suele tener un efecto más intenso, mientras que la galleta es ideal para una experiencia más moderada. ¿Te gustaría que te ayude a realizar un pedido de alguno hoy?', 647, 0, '"2026-09-05T21:48:04.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (455, 8, 17, 'general', 'gemini', 'No obvio no', '¡Hola! Soy Asistente de Admin NOMA, un gusto saludarte. Entiendo que estás ocupada, así que quedo atento para cuando necesites ayuda con algún pedido o consulta sobre nuestros productos.', 287, 0, '"2026-09-05T21:48:04.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (456, 8, 17, 'general', 'gemini', 'Voy', 'Entendido, estaré atento. ¿Deseas realizar algún pedido o necesitas ayuda con información sobre nuestros productos?', 329, 0, '"2026-09-05T21:48:04.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (457, 8, 22, 'general', 'gemini', 'Y tu?', '¡Hola! Soy Asistente de Admin NOMA, un gusto saludarte. Te cuento que el brownie es el favorito por su intenso sabor a chocolate, pero la galleta es ideal si buscas algo más crujiente; ¡ambos son deliciosos! ¿Te gustaría que te anote un brownie o una galleta para tu pedido?', 258, 0, '"2026-09-05T21:48:04.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (458, 8, 22, 'general', 'gemini', 'Aún tienes?', '¡Hola! Sí, aún tenemos disponibilidad. Tanto nuestras galletas como los brownies son deliciosos, pero muchos de nuestros clientes prefieren el brownie por su textura intensa. ¿Te gustaría realizar un pedido para el bloque 13?', 284, 0, '"2026-09-05T21:48:04.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (459, 8, 17, 'general', 'gemini', 'Se me hizo tarde jajajaja', '¡No te preocupes, suele pasar! Aquí estoy para ayudarte cuando estés lista; dime, ¿en qué producto o servicio de Admin NOMA puedo apoyarte hoy?', 336, 0, '"2026-09-05T21:48:05.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (460, 8, 22, 'general', 'gemini', 'Donde es que pena', '¡Hola! Qué gusto saludarte de nuevo. Sobre tu duda, ambos son deliciosos, pero si buscas algo intenso y chocolatoso, el brownie es el favorito; si prefieres algo crujiente, la galleta es ideal.
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (461, 8, 17, 'general', 'gemini', 'Me hicieron subir al eginopiso', '¡Entiendo! Lamento que hayas tenido un contratiempo, aquí estaré cuando estés lista. ¿Hay algo en lo que pueda apoyarte con tus productos o servicios de Admin NOMA?', 348, 0, '"2026-09-05T21:48:05.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (462, 8, 17, 'soporte', 'soporte', 'El problema es q si me escriben', 'Entiendo perfectamente, no te preocupes por el inconveniente. Cuando tengas un momento, dime en qué producto estás interesada y con gusto te ayudaré a gestionar tu pedido.', 386, 0, '"2026-09-05T21:48:05.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (463, 8, 22, 'general', 'gemini', 'Gracias', '¡Hola! Con gusto te ayudo, ¿qué producto deseas pedir para el bloque 13? Ambos, el brownie y la galleta, son deliciosos, pero el brownie es nuestro favorito por su textura intensa.', 280, 0, '"2026-09-05T21:48:05.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (464, 8, 17, 'error', 'none', 'Tienen q hacer Comi un papel', 'Disculpa, el servicio de IA está temporalmente no disponible. Intenta de nuevo en un momento.', 0, 0, '"2026-09-05T21:48:05.000Z"');
