INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (510, 8, 19, 'general', 'gemini', 'nos comimos una entre 4', '¡Qué bueno que la hayan disfrutado! Si desean realizar un nuevo pedido, con gusto puedo ayudarte a gestionarlo ahora mismo. ¿Qué les gustaría ordenar?', 357, 0, '"2026-09-05T22:45:38.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (511, 8, 19, 'general', 'gemini', 'y aún así nos cogió re duro jajajajajajaja', '¡Vaya, parece que la experiencia fue bastante potente! Si desean repetir o probar algo diferente, estoy aquí para ayudarles con su próximo pedido. ¿En qué más puedo colaborarles hoy?', 681, 0, '"2026-09-05T22:45:40.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (512, 8, 19, 'general', 'gemini', 'hasta a mí que yo ya le tengo tolerancia', 'Nuestros productos están diseñados para ofrecer la mejor calidad y experiencia, ¡qué bueno que notaste la diferencia! Quedo a tu disposición por si deseas realizar un nuevo pedido o tienes alguna duda adicional.', 738, 0, '"2026-09-05T22:45:43.000Z"');
INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (513, 8, 19, 'general', 'gemini', 'que viaje', 'Parece que fue una experiencia inolvidable. Si deseas encargar algo más para tu próximo "viaje", solo dímelo y con gusto te ayudaré con el pedido.', 431, 0, '"2026-09-05T22:46:15.000Z"');
