INSERT INTO agente_logs (id, negocio_id, cliente_id, intencion_detectada, agente_utilizado, mensaje_entrada, respuesta_texto, tokens_usados, tiempo_respuesta_ms, created_at) VALUES (515, 8, 24, 'general', 'gemini', 'Oe', '¡Hola! Soy el Asistente de Admin NOMA, un gusto saludarte. ¿En qué puedo ayudarte hoy o qué información necesitas sobre nuestros productos?', 409, 0, '"2026-09-05T22:46:19.000Z"');
